.editorx-ai-orb { position: relative; display: inline-block; border-radius: 9999px; overflow: visible; }
.editorx-ai-orb > i { position: absolute; inset: 0; border-radius: inherit; display: block; }
.editorx-ai-orb .orb-halo {
  inset: -40%;
  background: radial-gradient(circle, rgba(52, 211, 153, .6), rgba(56, 189, 248, .3) 45%, transparent 70%);
  filter: blur(4px);
  animation: editorx-orb-breathe 4s ease-in-out infinite;
}
/* Colour surface: turns so the hue drifts. */
.editorx-ai-orb .orb-a {
  background: conic-gradient(from 0deg, #34d399, #38bdf8, #a78bfa, #34d399);
  animation: editorx-orb-spin 10s linear infinite;
}
/* A deep shaded pool and a bright highlight on opposite sides, sweeping
