.editorx-ai-orb .orb-b {
  background: radial-gradient(circle at 78% 72%, rgba(79, 70, 229, .9), rgba(79, 70, 229, 0) 52%);
  animation: editorx-orb-spin 6s linear infinite;
}
.editorx-ai-orb .orb-c {
