  animation: editorx-orb-spin 6s linear infinite;
}
@keyframes editorx-orb-spin { to { transform: rotate(360deg); } }
@keyframes editorx-orb-breathe { 0%, 100% { opacity: .4; transform: scale(.8); } 50% { opacity: 1; transform: scale(1.15); } }
@media (prefers-reduced-motion: reduce) {
  .editorx-ai-orb .orb-halo, .editorx-ai-orb .orb-a, .editorx-ai-orb .orb-b, .editorx-ai-orb .orb-c { animation: none; }
